use std::{collections::HashSet,fs};
use lex_core::Provision;
fn main(){
 let all:Vec<Provision>=serde_json::from_str(&fs::read_to_string("/Users/jr/Dev/lex-mex/corpus/mx/lritf/provisions.json").unwrap()).unwrap();
 let ext="urn:lex-mx:federal:constitution:cpeum";
 let opts=lex_parse::ReferenceOptions{policy:lex_parse::InstrumentContextPolicy::SentenceEarliestMarker{internal_markers:vec!["de esta ley".into()],external_instruments:vec![("constitución política de los estados unidos mexicanos".into(),ext.into())]},transitory_citations:true,same_article_fractions:true,relative_references:true,historical_targets:vec![]};
 for text in [
 "Se aplicará el artículo 1. La Constitución Política de los Estados Unidos Mexicanos reconoce derechos.",
 "Se aplicará el artículo 1; la Constitución Política de los Estados Unidos Mexicanos reconoce derechos.",
 "Se aplicará el artículo 1, segundo párrafo de esta Ley.",
 "Se aplicará el artículo 1, 2o. párrafo de esta Ley.",
 "Se aplicará el artículo 1, párrafo 2 de esta Ley.",
 "Se aplicará el artículo 1, fracción II, 2o. párrafo de esta Ley.",
 "Se aplicarán los artículos 1 a 3 de esta Ley.",
 "Se aplicará la fracción II del artículo 1 de esta Ley.",
 "Se aplicará el inciso a) del artículo 1 de esta Ley.",
 "Se aplicará la fracción II, inciso a) del artículo 1 de esta Ley.",
 "Se aplicará el artículo 1 del preconstitución política de los estados unidos mexicanosismo.",
 ] {
 let mut ps=all[..3].to_vec();ps[1].text=text.into();
 let mut targets:HashSet<_>=ps.iter().map(|p|p.id.clone()).collect();targets.insert(format!("{ext}:article:1"));
 let refs=lex_parse::extract_references(&ps,None,&opts,&targets).unwrap();
 println!("INPUT: {text}");
 for e in refs.iter().filter(|e|e.source_provision_id==ps[1].id){println!("{} -> {} {:?} QUALIFIERS={:?}",e.source_span,e.target_provision_id,e.resolution_status,e.qualifiers.iter().map(|q|&q.text).collect::<Vec<_>>());}
 }

 let social="urn:lex-mx:federal:statute:lss";
 let opts=lex_parse::ReferenceOptions{policy:lex_parse::InstrumentContextPolicy::SentenceEarliestMarker{internal_markers:vec!["de esta ley".into()],external_instruments:vec![("ley del seguro social".into(),social.into())]},transitory_citations:true,same_article_fractions:true,relative_references:true,historical_targets:vec![]};
 for text in ["Se aplicará el artículo 1 de la Ley del Seguro Social.","Se aplicará el artículo 1 de la Ley del Seguro Socialista."] {
 let mut ps=all[..3].to_vec();ps[1].text=text.into();let mut targets:HashSet<_>=ps.iter().map(|p|p.id.clone()).collect();targets.insert(format!("{social}:article:1"));
 let refs=lex_parse::extract_references(&ps,None,&opts,&targets).unwrap();println!("INPUT: {text}");for e in refs.iter().filter(|e|e.source_provision_id==ps[1].id){println!("{} -> {} {:?} QUALIFIERS={:?}",e.source_span,e.target_provision_id,e.resolution_status,e.qualifiers.iter().map(|q|&q.text).collect::<Vec<_>>());}
 }
}
